 if(action==='narrate'){if(!('speechSynthesis' in window))return toast(t('narrationUnavailable'));if(speechSynthesis.speaking){speechSynthesis.cancel();el.innerHTML=ico('play',13)+t('playNarration');return;}const utterance=new SpeechSynthesisUtterance($('#slide-body').textContent);utterance.lang=ll()==='en'?'en-US':ll();utterance.rate=.93;utterance.onend=()=>{if(el.isConnected)el.innerHTML=ico('play',13)+t('playNarration');};utterance.onerror=()=>toast(t('narrationUnavailable'));speechSynthesis.speak(utterance);el.innerHTML=ico('stop',13)+t('stopNarration');}
