document.addEventListener('submit',async e=>{
 const f=e.target;if(!['new-course-form','new-class-form','import-form','chat-form'].includes(f.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));
 if(f.id==='new-course-form'){
  const generationUser=accountUser?.id;
  if(!data.topic.trim())return toast(t('required'));const personal=f.dataset.personal==='true',language=data.language;
  const c={id:'course-'+crypto.randomUUID(),title:{[language]:data.topic.trim()},description:{[language]:data.requirements.trim()},topic:'foundations',duration:20,status:'draft',theme:'mint',personal,lessons:[]};
  if(e.submitter?.value==='template'){Object.assign(c,academy.template(data.topic.trim(),c.id),{personal,status:'draft'});}
  else if(e.submitter?.value==='ai'){
   const buttons=f.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);$('#generation-result').textContent=generationNotice();
   try{const response=await aiRequest('generate',{language,topic:data.topic,requirements:data.requirements,profile:state.profile});const draft=response.course;c.title={[language]:draft.title};c.description={[language]:draft.description};c.lessons=draft.lessons.map(l=>({id:'l-'+crypto.randomUUID(),title:{[language]:l.title},body:{[language]:l.body},advanced:{[language]:l.advanced||l.body},type:'read'}));c.duration=c.lessons.length*7;}
   catch(err){Object.assign(c,academy.template(data.topic.trim(),c.id),{personal,status:'draft',generationFallback:true});}
  }else c.lessons=[{id:'l-'+crypto.randomUUID(),title:{[language]:data.topic.trim()},body:{[language]:data.requirements.trim()},advanced:{[language]:''},type:'read'}];
  if(generationUser!==accountUser?.id)return;
  persistCourse(c);if(f.isConnected){editorDraft=structuredClone(c);editorLang=language;closeModal();go('editor/'+c.id);}toast(t('created'));
 }
 if(f.id==='new-class-form'){if(!data.name.trim()||!getCourse(data.courseId))return toast(t('required'));state.classes.push({id:'class-'+crypto.randomUUID(),name:data.name.trim(),courseId:data.courseId,students:[]});save();closeModal();render();toast(t('saved'));}
 if(f.id==='import-form'){const roster=parseRoster(data.csv);if(!roster.length)return toast(t('invalidCsv'));const c=state.classes.find(c=>c.id===f.dataset.id);const emails=new Set(c.students.map(s=>s.email));const added=roster.filter(s=>!emails.has(s.email));c.students.push(...added);save();closeModal();render();toast(t('imported')+' · '+added.length);}
 if(f.id==='chat-form'){
  const ctx=chatContext;if(!ctx)return;const message=data.message.trim();if(!message)return;const c=getCourse(ctx.courseId),l=c.lessons[ctx.index];chatMessages.push({role:'user',content:message});$('#chat-box').insertAdjacentHTML('beforeend',`<div class="chat-message user">${esc(message)}</div>`);f.reset();const btn=f.querySelector('button');btn.disabled=true;btn.textContent=t('thinking');
  try{const response=await aiRequest(ctx.roleplay?'roleplay':'tutor',{profile:state.profile,roleplayMode:l.mockInterview?'interviewer':'stakeholder',context:learnText(c.title)+'\n'+learnText(l.title)+'\n'+learnText(l.body)+(l.interview?'\nAuthored practice extracts:\n'+l.interview.map(x=>learnText(x.person)+': '+learnText(x.question)+' '+learnText(x.answer)).join('\n'):''),messages:chatMessages.slice(-12)},ctx.controller.signal);if(chatContext!==ctx)return;chatMessages.push({role:'assistant',content:response.content});$('#chat-box').insertAdjacentHTML('beforeend',`<div class="chat-message">${esc(response.content)}</div>`);$('#chat-box').scrollTop=$('#chat-box').scrollHeight;event('ai',c.id,{lessonId:l.id});}
  catch(err){if(err.name!=='AbortError'&&chatContext===ctx)toast(err.message);}
  finally{if(btn.isConnected){btn.disabled=false;btn.innerHTML=t('send')+ico('arrow',13);f.querySelector('input').focus();}}
 }
});
