void refreshAIConfiguration();
window.addEventListener('focus',()=>void refreshAIConfiguration());
function aiConfigurationText(){
 if(aiStatus==='ready')return t('generateHint');
 if(aiStatus==='missing')return t('aiOff');
 return state.lang==='en'?(aiStatus==='loading'?'Checking AI configuration…':'Unable to check AI connection. Please retry.'):(aiStatus==='loading'?(state.lang==='zh-TW'?'正在檢查 AI 設定…':'正在检查 AI 配置…'):(state.lang==='zh-TW'?'暫時無法確認 AI 連線，請重試。':'暂时无法确认 AI 连接，请重试。'));
}
async function refreshAIConfiguration(){
 if(aiCheckPromise)return aiCheckPromise;
 aiCheckPromise=(async()=>{
  try{const response=await fetch('/api/ai',{cache:'no-store',credentials:'same-origin',signal:AbortSignal.timeout(8000)});if(!response.ok)throw Error('status_unavailable');const data=await response.json();if(typeof data.configured!=='boolean')throw Error('invalid_status');aiConfigured=data.configured;aiStatus=aiConfigured?'ready':'missing';}
  catch{aiConfigured=false;aiStatus='unavailable';}
  finally{document.querySelectorAll('.ai-indicator').forEach(el=>{el.outerHTML=aiIndicator();});document.querySelectorAll('[data-ai-config-status]').forEach(el=>{el.textContent=aiConfigurationText();el.classList.toggle('warning',!aiConfigured);});document.querySelectorAll('#new-course-form button[value=ai]').forEach(button=>{button.disabled=!aiConfigured;});aiCheckPromise=null;}
 })();
 return aiCheckPromise;
}

async function acceptAccount(user,restoreRoute=false){
 workspaceSync.stop();if(accountUser)cacheWorkspace();
 const language=state.lang;KEY='forma.workspace.v1.user.'+user.id;let hasLocalData=false;
 try{const saved=localStorage.getItem(KEY);hasLocalData=!!saved;if(saved)try{const backup='forma.workspace.pre-cloud.v1.user.'+user.id;if(!localStorage.getItem(backup))localStorage.setItem(backup,saved);}catch{/* A full browser cache must not discard existing learning records. */}state={...fresh(),...JSON.parse(saved||'null')};activateGitUser(user.id);}catch{state=fresh();}
 state.lang=language;state.role=accountRole(user);state.profile={...fresh().profile,...state.profile};accountUser=user;adoptAccountName();
 accountChecked=false;editorDraft=null;closeModal();render();
 await workspaceSync.start(user.id,{hasLocalData});adoptAccountName();accountChecked=true;cacheWorkspace();
 if(state.profile.name===user.username)workspaceSync.changed();
 const teacher=user.role==='teacher',admin=user.role==='admin';
 const keepPage=restoreRoute&&(route()[0]==='courseware-example'||(teacher?['courses','teacher-course','classrooms','engagement','profile'].includes(route()[0]):admin?['overview','users','catalog','admin-learning','profile'].includes(route()[0]):!['login','register'].includes(route()[0])));
 if(!keepPage)location.hash=teacher?'courses':admin?'overview':'learning';
 render();
}
async function checkAccount(){
 try{const {user}=await cloudAPI('/api/account');if(user){await acceptAccount(user,true);return;}accountChecked=true;location.hash='login';render();}
 catch{$('#app').innerHTML='<main class="auth-page"><section class="panel"><p>连接失败，请重试 / Unable to connect</p><button class="btn" id="account-retry">重试 / Retry</button></section></main>';$('#account-retry').onclick=checkAccount;}
}

window.addEventListener('forma-signed-out',()=>{cacheWorkspace();workspaceSync.stop();accountUser=null;closeModal();location.hash='login';render();});
